mapper.update:
/*updateSellerMpStToolStockState_KEP_S_STOCK*/

		UPDATE 
		    KEP_S_STOCK /* 구매대행재고수불 */
		SET STOCK_QTY      = #{st_stock_qty}
		  , CHANGE_USER_ID = #{st_user_id}
		  , CHANGE_DATE    = TO_CHAR(SYSDATE, 'YYYYMMDD')
		  , CHANGE_TIME    = TO_CHAR(SYSDATE, 'HH24MISS')
		WHERE 1=1
		AND BUYER         = #{st_buyer}
		AND BUYER_ITEM_NO = #{st_buyer_item_no}
		AND SELLER        = #{st_com_code}

/*updateSellerMpStToolStockState_ICOMCQDT*/

		UPDATE 
		    ICOMCQDT /* 구매사별 계약서 가격정보 */
		SET S_STOCK_FLAG = 'N'
		WHERE 1=1
		AND BUYER         = #{st_buyer}
		AND BUYER_ITEM_NO = #{st_buyer_item_no}
		AND CONTRACT_NO   = #{st_contract_no}
		AND CONTRACT_SEQ  = #{st_contract_seq}

/*deleteSellerMpStToolStockState*/

		DELETE FROM 
		    KEP_S_STOCK /* 구매대행재고수불 */
		WHERE 1=1
		AND BUYER         = #{st_buyer}
		AND BUYER_ITEM_NO = #{st_buyer_item_no}
		AND SELLER        = #{st_com_code}
